local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["58039185e73fb90c"] = { "Abbiamo metà del silithyst che ci serve. Non fermarti ora!", "." },
  ["58047f17b13694fa"] = { "Il sole è già sorto? Le ore della notte non bastano mai! Be', Saelienne si prenderà cura di te. La trovi mentre si occupa dei suoi ospiti nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, nella parte nord-orientale di Darnassus.", "." },
  ["5806712a1f6bc925"] = { "Preso uno! Vediamo se qualche guardia ha fame. Andiamo, Fang!", "." },
  ["5807dccb1af5f3c5"] = { "Basta lingotti di stagno! Mi fanno male persino le braccia a forza di impilarli. Abbiamo tutto quello che ci serve, quindi chiedi a qualcun altro se ha bisogno che tu raccolga qualcosa.", "." },
  ["580a82b8dd93fc75"] = { "Andiamo, goblin!", "." },
  ["580f5a872dba16ec"] = { "Quello è vuoto!!", "." },
  ["581aff3669ce4a83"] = { "%s mette la testa di Marg nel calderone.", "." },
  ["581e27df0c98aade"] = { "Consegnami la tua anima, mortale.", "." },
  ["581eaf593fcdae4d"] = { "E pensare che un giorno le storie leggendarie potrebbero parlare proprio di te!", "." },
  ["582094560db2e7b2"] = { "Mmh... le cose che devi imparare vanno un po' oltre le mie capacità. Fai due chiacchiere con Sellandus da Larson's Clothiers, appena più su lungo il sentiero, sulla destra. Mi ha insegnato tutto quello che so!", "." },
  ["5823558718b16bc2"] = { "Non tutti i Tauren disprezzano la tua gente, {race}. Ahimè, mi è proibito offrirti i miei servigi.", "." },
  ["5825661d6eb3eae6"] = { "Non è la piccola creazione più straordinaria che ci sia?", "." },
  ["582682832c95f2be"] = { "Osi mettere piede nel ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧, verme?", "." },
  ["5826ab0704d17711"] = { "La nostra alchimista si chiama Carolai Anise. La trovi in una casa all'estremità nord-occidentale di Brill.", "." },
  ["5829558283463b5b"] = { "Salute, <viaggiatore/viaggiatrice>. La mia vista sarà anche debole, ma sento i passi di <un/una> {class} a un miglio di distanza. Per anni ho difeso ⟦Stormwind=Roccavento⟧ con orgoglio, ma quando la vista mi ha abbandonato ho dovuto ritirarmi.", "." },
  ["5831ac24a88a3d36"] = { "State indietro, creature immonde!", "." },
  ["5834a2f0832e56f8"] = { "Vuoi comprare uno scarafaggio?", "." },
  ["584447a109b1b683"] = { "Le mie macchine sono il futuro! Vi distruggeranno tutti!", "." },
  ["58477f3229ac1906"] = { "Come vuoi. Quella feccia dell'⟦Horde=Orda⟧, ripugnante e trasandata...", "." },
  ["585665da265a5615"] = { "%s getta la spada nella pozza poco profonda.", "." },
  ["5857d51b7d0321f6"] = { "{name}, eccoti di ritorno! Gli spiriti del mio ultimo pasto dicevano che mi avresti fatto visita e che avremmo parlato d'affari.\n\nAvevano ragione?", "." },
  ["5861dbe3c52e5982"] = { "È piuttosto semplice, {name}. La mia vecchia compagnia di mercenari, The Veiled Blade, ha accettato la missione sbagliata nel momento sbagliato.\n\nCi aveva assunti un contrabbandiere goblin di ⟦Booty Bay=Baia del Bottino⟧, un certo Gremnik Rizzlesprang, che bramava il libro degli incantesimi di lord Valthalak. O forse c'era una vecchia rivalità di mezzo? Immagino che ormai non lo sapremo mai, perché Gremnik è stato ucciso non molto tempo fa da un gruppo di assassini spettrali di Valthalak. Possono essere davvero letali quando si radunano in gran numero.\n\nDove eravamo?", "." },
  ["58624ceb3c2fb847"] = { "C'è ancora molto lavoro da fare, {name}! Continua ad abbattere i nostri nemici!", "." },
  ["5865586b14476b17"] = { "Combattenti pronti... COMBATTETE!", "." },
  ["58720edf220ca085"] = { "Sono il re serpente! Posso fare qualsiasi cosa!", "." },
  ["587631d77694a2e3"] = { "Vogliamo solo sapere perché i silvagufi sorvegliano questa zona...", "." },
  ["5881fca019356d19"] = { "Chi devo uccidere?", "." },
  ["588334caebbdeff0"] = { "Bene, è qui che dobbiamo stare all'erta con tutte e quattro le zampe. Preparati!", "." },
  ["58879694284c0efd"] = { "Se preferisci cacciare all'aperto, sia i treant di Vilbosco sia i lasher di Un'Goro sono un'ottima fonte di fronde.\n\nSe ami di più il rischio, le ali est e ovest di ⟦Dire Maul=Maglio Infausto⟧ ti forniranno una scorta quasi illimitata di fronde selvagge.", "." },
  ["588eb0f360330512"] = { "Oh, intendi la tesoreria di ⟦Stormwind=Roccavento⟧. Non è lontana dalle porte, appena entri a ⟦Stormwind=Roccavento⟧.", "." },
  ["5890c669deb1ec6b"] = { "Salve, {name}! Se non lo vedi nella mia bottega, è molto probabile che io possa procurartelo!", "." },
  ["58927aae863b0292"] = { "Il Custode del Sapere è un antico. Ha servito la nostra gloriosa Regina!", "." },
  ["589a8195cb20ef00"] = { "Ohi... un paladino? Beh, <ragazzo/ragazza>, ti va bene! Azar Stronghammer è tornato dall'addestramento e al momento alloggia alla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧ di Kharanos.", "." },
  ["589c40b0633881c2"] = { "%s consegna un messaggio allo speziale Zamah.", "." },
  ["589f6d9288e318e2"] = { "Le guardie del re dovrebbero arrivare a breve a ritirare il Memoriale. Nel frattempo, raggiungimi di sopra e finiamo la nostra chiacchierata, {name}.", "." },
  ["58a6222f9c50cb78"] = { "Sayoc è il maestro d'armi orco. Si trova nella ⟦Valley of Honor=Valle dell'Onore⟧ di Orgrimmar. Può insegnare l'uso di archi, pugnali, armi da pugno, asce a una e a due mani e armi da lancio.\n\nHanashi, il maestro d'armi troll nella ⟦Valley of Honor=Valle dell'Onore⟧ di Orgrimmar, può insegnare l'uso di archi, asce a una e a due mani, bastoni e tutte le armi da lancio.\n\nAnsekhwa, il maestro d'armi tauren, si trova sull'altura inferiore di Picco del Tuono. Insegna l'uso di mazze a una e a due mani, bastoni e armi da fuoco.", "." },
  ["58a7cc92ce53831a"] = { "Guardali correre!", "." },
  ["58a89fd00e9c8cbe"] = { "Non te lo direi neanche se lo sapessi! Perché appena lo faccio, mi allontano da questi cristalli...", "." },
  ["58a9009d1083ad7d"] = { "punto di conquista Contested1", "." },
  ["58a9009e1083ad7e"] = { "punto di conquista Contested2", "." },
  ["58ab65d33c8ad7dc"] = { "Gli spiriti mi sussurrano all'orecchio. Sono inquieti e pieni di angoscia.", "." },
  ["58ba12aeb98c4864"] = { "Aku'mai evocherà di certo gli Dei Antichi per noi. Se solo riuscissimo a fornire abbastanza innocenti da saziare la sua fame.", "." },
  ["58bb02898f3df6ea"] = { "Come faccio?", "." },
  ["58c0eb0554a18937"] = { "Va bene, vado! Smettila di urlare!", "." },
  ["58c9f986cbecad8f"] = { "Ehi-oh, ehi-oh, e tutto il resto... muoviamoci.", "." },
  ["58ce7406d4f88db5"] = { "Se cerchi informazioni che il ⟦Cenarion Circle=Circolo Cenariano⟧ potrebbe aver archiviato da qualche parte, sono io la persona giusta. D'altra parte, prima che possa davvero aiutarti, devi sapere quali informazioni cerchi.\n\nVisto come funziona? Geniale!", "." },
  ["58d22665a1372849"] = { "Il tuo capo risiede alle porte di Naxxramas. Pensi che non senta la pressione?", "." },
  ["58e4fb8bcb1c29ef"] = { "Mi piacerebbe tanto avere uno di quei biglietti della fortuna di cui parlavi! Ho spazio nell'inventario.", "." },
  ["58e5d795eafd567b"] = { "Faccio parte dei Sette, ed è nostro destino montare la guardia. Per sempre.", "." },
  ["58e6a056dc9d1378"] = { "Warg, sei quasi pronto a mangiare? Comincio a preparare.", "." },
  ["58ec0561b419e1dc"] = { "Vedo che imparerai in fretta. Per me è un bene, perché di questi tempi ho sempre da fare. Anzi, mi hai fatto venire in mente una cosa: potresti sbrigare una piccola commissione per me?", "." },
  ["58f7b826e1f2b772"] = { "Pane fresco! Pane appena sfornato, qui!", "." },
  ["58f98e3f8174ac5b"] = { "Porto con me entrambe le parti dello scettro.", "." },
  ["58fd549b429f4a52"] = { "Fimble Finespindle ha una bottega sul lato nord-occidentale della ⟦Great Forge=Grande Forgia⟧. Scommetto che potrebbe mostrarti come fabbricare un'ottima armatura.", "." },
})
